/*!40000 ALTER TABLE `movies` DISABLE KEYS */;
INSERT INTO `movies` VALUES (1,'QUỸ ĐẠO CUỐI CÙNG','Khoa học viễn tưởng',128,'Một tín hiệu từ rìa vũ trụ đưa phi hành đoàn Vega đến hành trình vượt qua giới hạn của không gian, thời gian và chính mình.','/images/orbit.svg','T13','2026-10-21 00:00:00.000000','ARCHIVED'),(2,'THÀNH PHỐ SAU CƠN MƯA','Tình cảm',112,'Giữa những con phố quen thuộc, hai người xa lạ tìm thấy nhau qua một cuốn sổ bị bỏ quên.','/images/rain.svg','T13','2026-10-21 00:00:00.000000','ARCHIVED'),(3,'MẬT MÃ BÓNG ĐÊM','Hành động',118,'Một chuyên gia giải mã phải lựa chọn giữa sự thật và an toàn của thành phố khi đêm cuối cùng bắt đầu.','/images/night.svg','T16','2026-10-21 00:00:00.000000','ARCHIVED'),(4,'KHU RỪNG KỲ DIỆU','Hoạt hình',96,'Cùng những người bạn nhỏ đi qua khu rừng phát sáng để tìm lại ngôi sao đã rơi khỏi bầu trời.','/images/forest.svg','P','2026-10-21 00:00:00.000000','ARCHIVED'),(5,'CHẠM VÀO MÙA HẠ','Tâm lý',105,'Một mùa hè bên biển, những lời hứa cũ và cơ hội bắt đầu lại của những người bạn thời niên thiếu.','/images/summer.svg','T13','2026-10-21 00:00:00.000000','ARCHIVED'),(6,'ĐƯỜNG ĐUA VÔ TẬN','Hành động',124,'Tay đua trẻ bước vào giải đấu quyết định, nơi mỗi khúc cua là một lựa chọn không thể quay lại.','/images/race.svg','T16','2026-10-21 00:00:00.000000','ARCHIVED'),(7,'HÀNH TINH XANH','Phiêu lưu',121,'Hành trình khám phá thế giới đại dương và những điều kỳ diệu đang chờ được gìn giữ.','/images/planet.svg','P','2026-11-02 00:00:00.000000','ARCHIVED'),(8,'NGƯỜI GIỮ NHỮNG VÌ SAO','Kỳ ảo',116,'Khi những vì sao lần lượt biến mất, người giữ đèn cuối cùng bắt đầu một chuyến đi không bản đồ.','/images/stars.svg','T13','2026-11-08 00:00:00.000000','ARCHIVED'),(9,'ALWAYS ALISA','Phim điện ảnh',120,'Poster được cung cấp trong bộ sưu tập Phim. Nội dung chi tiết đang được cập nhật. Thời lượng, ngày khởi chiếu và lịch chiếu hiện là dữ liệu demo phục vụ trải nghiệm đặt vé.','/images/movies/always-alisa.jpg','Chưa rõ','2026-10-21 00:00:00.000000','NOW_SHOWING'),(10,'AVENGERS HỒI KẾT - PHIÊN