DROP TABLE IF EXISTS `showtimes`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `showtimes` (
  `Id` int NOT NULL AUTO_INCREMENT,
  `MovieId` int NOT NULL,
  `ScreeningRoomId` int NOT NULL,
  `StartsAtUtc` datetime(6) NOT NULL,
  `EndsAtUtc` datetime(6) NOT NULL,
  `StandardPrice` decimal(14,2) NOT NULL,
  `VipPrice` decimal(14,2) NOT NULL,
  `IsActive` tinyint(1) NOT NULL,
  PRIMARY KEY (`Id`),
  KEY `IX_Showtimes_MovieId_StartsAtUtc` (`MovieId`,`StartsAtUtc`),
  KEY `IX_Showtimes_ScreeningRoomId_StartsAtUtc_EndsAtUtc` (`ScreeningRoomId`,`StartsAtUtc`,`EndsAtUtc`),
  CONSTRAINT `FK_Showtimes_Movies_MovieId` FOREIGN KEY (`MovieId`) REFERENCES `movies` (`Id`) ON DELETE RESTRICT,
  CONSTRAINT `FK_Showtimes_ScreeningRooms_ScreeningRoomId` FOREIGN KEY (`ScreeningRoomId`) REFERENCES `screeningrooms` (`Id`) ON DELETE RESTRICT
) ENGINE=InnoDB AUTO_INCREMENT=392 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
