--
-- Table structure for table `showtimeseats`
--

DROP TABLE IF EXISTS `showtimeseats`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `showtimeseats` (
  `Id` int NOT NULL AUTO_INCREMENT,
  `ShowtimeId` int NOT NULL,
  `SeatId` int NOT NULL,
  `Status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `HoldBookingId` char(36) CHARACTER SET ascii COLLATE ascii_general_ci DEFAULT NULL,
  `HoldExpiresAtUtc` datetime(6) DEFAULT NULL,
  `Price` decimal(14,2) NOT NULL,
  PRIMARY KEY (`Id`),
  UNIQUE KEY `IX_ShowtimeSeats_ShowtimeId_SeatId` (`ShowtimeId`,`SeatId`),
  KEY `IX_ShowtimeSeats_HoldBookingId_Status` (`HoldBookingId`,`Status`),
  KEY `IX_ShowtimeSeats_SeatId` (`SeatId`),
  CONSTRAINT `FK_ShowtimeSeats_Bookings_HoldBookingId` FOREIGN KEY (`HoldBookingId`) REFERENCES `bookings` (`Id`) ON DELETE RESTRICT,
  CONSTRAINT `FK_ShowtimeSeats_Seats_SeatId` FOREIGN KEY (`SeatId`) REFERENCES `seats` (`Id`) ON DELETE RESTRICT,
