CREATE TABLE `transactionlogs` (
  `Id` bigint NOT NULL AUTO_INCREMENT,
  `BookingId` char(36) CHARACTER SET ascii COLLATE ascii_general_ci DEFAULT NULL,
  `Event` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `Message` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `CreatedAtUtc` datetime(6) NOT NULL,
  PRIMARY KEY (`Id`),
  KEY `IX_TransactionLogs_BookingId` (`BookingId`),
  KEY `IX_TransactionLogs_CreatedAtUtc` (`CreatedAtUtc`),
  CONSTRAINT `FK_TransactionLogs_Bookings_BookingId` FOREIGN KEY (`BookingId`) REFERENCES `bookings` (`Id`) ON DELETE RESTRICT
) ENGINE=InnoDB AUTO_INCREMENT=76 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
